-- Catalog and reference data plus six synthetic fixture users with profiles.
-- Interaction content (topics, rules, evidence) is not seeded here: it comes
-- from the MD workbook import, db/init/006_md_workbook_import.sql, generated by
-- db/tools/import_md_workbook.py. One transaction so the file applies atomically.
BEGIN;







-- No other acting user exists for seed users, so self-reference them, as the
-- backend does for self-registration (see wiki/backend.md). Other seed rows
-- leave created_by/updated_by NULL: there is no acting user for fixture data.
UPDATE users SET created_by = id, updated_by = id;
























SELECT setval(pg_get_serial_sequence('user_roles', 'id'), (SELECT max(id) FROM user_roles));
SELECT setval(pg_get_serial_sequence('units', 'id'), (SELECT max(id) FROM units));
SELECT setval(pg_get_serial_sequence('data_sources', 'id'), (SELECT max(id) FROM data_sources));
